local a=require("fcs.io.hwconfig")local b={}function b.bind(c,d,e)if c.thrusters[d]~=nil then c.thrusters[d]=e elseif c.sensors[d]~=nil then c.sensors[d]=e elseif d=="fuelRelay"then c.fuelRelay=e end;return c end;function b.measureWrite(f,g,h)local i=os.epoch("utc")for j=1,h do f:setThruster(g,j%2==0)end;return(os.epoch("utc")-i)/h end;local k="/eh2_hw_config.tbl"local function l()local m;if fs.exists(k)then local n=fs.open(k,"r")m=textutils.unserialise(n.readAll()or"")n.close()end;return a.merge(m or{},a.defaults())end;local function o(p)local n=fs.open(k,"w")n.write(textutils.serialise(p))n.close()end;local function q(r)for s,e in ipairs(r.getNames())do print(e.."  ["..tostring(r.getType(e)).."]")end end;function b.run()local r=require("fcs.io.shim")local t=require("fcs.io.backend")local c=l()while true do print("\n== EH2 PROBE == 1 discover 2 bind 3 sensors 4 thruster 5 timing 6 roles 7 methods q quit")local u=read()if u=="1"then q(r)elseif u=="2"then write("role (e.g. FL / gimbal / fuelRelay): ")local d=read()write("peripheral name: ")local e=read()c=b.bind(c,d,e)o(c)print("bound "..d.." -> "..e)elseif u=="3"then local v=t.new(r,c)v:sensors()for s=1,10 do local w=v:sensors()print(("alt %.2f v %.2f pitch %.3f roll %.3f hdg %.3f yawR %.3f sway %.2f surge %.2f gnd %s"):format(w.altitude,w.vSpeed,w.pitch,w.roll,w.heading,w.yawRate,w.swayVel,w.surgeVel,tostring(w.onGround)))sleep(0.3)end elseif u=="4"then write("peripheral NAME (e.g. thruster_1): ")local e=read()local x=e~=""and r.wrap(e)or nil;if not x then print("no such peripheral: "..tostring(e))elseif not x.setPower then print(tostring(e).." has no setPower. Its methods:")local y=peripheral.getMethods(e)if y then local w=""for s,z in ipairs(y)do w=w..z.." "end;print(w)else print("(none)")end else x.setPower(15)sleep(0.5)print("thrustKN="..tostring(x.getCurrentThrustKN and x.getCurrentThrustKN()or"n/a"))x.setPower(0)end elseif u=="5"then write("peripheral NAME: ")local e=read()local x=e~=""and r.wrap(e)or nil;if 